#!/system/bin/sh
A="$TMPDIR"
[ -n "$A" ] && [ -d "$A" ] && [ -w "$A" ] || A=/data/local/tmp
[ -d "$A" ] && [ -w "$A" ] || A=/tmp
B="$A/.$$"
mkdir -m 700 -p "$B" 2>/dev/null || exit 1
trap 'rm -rf "$B"' 0 1 2 15
awk 'F{print} /^__ARMOR_PAYLOAD__$/{F=1}' "$0" | base64 -d > "$B/a" 2>/dev/null || exit 9
chmod 700 "$B/a" 2>/dev/null
case "$0" in
    /*) SA_SELF="$0" ;;
    *)  SA_SELF="$(cd "$(dirname "$0")" 2>/dev/null && pwd)/$(basename "$0")" ;;
esac
[ -f "$SA_SELF" ] || SA_SELF="$0"
SA_SELF="$SA_SELF" "$B/a" "$@"
C=$?
rm -rf "$B"
exit $C
